{
  "user_intent": {
    "original_question": "找出同时是演员和导演的人，分别计算他们作为演员和作为导演的作品平均评分，要求两种角色参演作品的平均评分都计算出来。",
    "domain": "imdb",
    "keywords": ["演员", "导演", "平均评分", "跨界者", "actor", "director", "average_rating"],
    "intent_type": "cross_over_artist_rating_comparison"
  },
  "entities": {
    "time_range": null,
    "filters": [
      {"field": "category_id", "operator": "IN", "value": "('actor','actress')", "role": "actor"},
      {"field": "category_id", "operator": "=", "value": "'director'", "role": "director"}
    ],
    "fields_to_display": ["人物名", "作为演员的平均评分", "作为导演的平均评分"]
  },
  "metrics": [
    {
      "name": "平均评分",
      "aliases": ["作品平均评分", "avg rating"],
      "formula": "AVG(t.average_rating)",
      "related_tables": ["titles", "principals", "names"],
      "aggregation": "AVG"
    }
  ],
  "business_rules": [
    {
      "id": "rule_actor",
      "name": "演员定义",
      "condition": "p.category_id IN ('actor', 'actress')"
    },
    {
      "id": "rule_director",
      "name": "导演定义",
      "condition": "p.category_id = 'director'"
    },
    {
      "id": "rule_rating",
      "name": "评分可信度",
      "condition": "t.average_rating IS NOT NULL"
    },
    {
      "id": "rule_movie",
      "name": "作品类型",
      "condition": "t.title_type = 'movie'"
    }
  ],
  "field_mappings": {
    "人物名": {"table": "names", "field": "primary_name"},
    "演员": {"table": "principals", "field": "category_id", "value": "('actor','actress')"},
    "导演": {"table": "principals", "field": "category_id", "value": "'director'"},
    "作品评分": {"table": "titles", "field": "average_rating"}
  },
  "historical_qa_pairs": [
    {
      "id": "hqa_cross_over",
      "original_question": "演而优则导 — 跨界者表现分析，找出同时是演员和导演的人，对比其作为演员 vs 导演的作品评分差异",
      "sql": "WITH actor_works AS (SELECT p.name_id, AVG(t.average_rating) AS actor_avg_rating, COUNT(*) AS actor_movie_count FROM principals p JOIN titles t ON p.title_id = t.id WHERE p.category_id IN ('actor', 'actress') AND t.title_type = 'movie' AND t.average_rating IS NOT NULL GROUP BY p.name_id HAVING COUNT(*) >= 3), director_works AS (SELECT p.name_id, AVG(t.average_rating) AS director_avg_rating, COUNT(*) AS director_movie_count FROM principals p JOIN titles t ON p.title_id = t.id WHERE p.category_id = 'director' AND t.title_type = 'movie' AND t.average_rating IS NOT NULL GROUP BY p.name_id HAVING COUNT(*) >= 2) SELECT n.primary_name, a.actor_movie_count, ROUND(a.actor_avg_rating, 2) AS actor_avg_rating, d.director_movie_count, ROUND(d.director_avg_rating, 2) AS director_avg_rating, ROUND(d.director_avg_rating - a.actor_avg_rating, 2) AS rating_difference FROM actor_works a JOIN director_works d ON a.name_id = d.name_id JOIN names n ON a.name_id = n.id ORDER BY rating_difference DESC LIMIT 20",
      "intent_type": "cross_over_artist_rating_comparison",
      "similarity_score": 0.95
    }
  ],
  "knowledge": [
    {
      "topic": "表关系",
      "content": "核心路径：titles ←→ principals ←→ names。titles.id = principals.title_id, principals.name_id = names.id"
    },
    {
      "topic": "演员定义",
      "content": "查询演员时必须同时包含 category_id IN ('actor', 'actress')"
    },
    {
      "topic": "导演定义",
      "content": "导演的 category_id = 'director'，不要用 job_id 查导演"
    },
    {
      "topic": "评分可信度",
      "content": "排名类查询应加 num_votes > 10000 过滤；average_rating 需 IS NOT NULL"
    }
  ],
  "context_summary": {
    "main_tables": ["names", "principals", "titles"],
    "main_fields": ["names.primary_name", "principals.name_id", "principals.category_id", "titles.average_rating", "titles.title_type"],
    "filter_conditions": ["p.category_id IN ('actor','actress')", "p.category_id = 'director'", "t.title_type = 'movie'", "t.average_rating IS NOT NULL"]
  },
  "metadata": {
    "phase": "knowledge_loaded",
